'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var zeros = require( '@stdlib/ndarray/zeros' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var getDtype = require( '@stdlib/ndarray/dtype' );
var getShape = require( '@stdlib/ndarray/shape' );
var getOrder = require( '@stdlib/ndarray/order' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var strides2offset = require( '@stdlib/ndarray/base/strides2offset' );
var numel = require( '@stdlib/ndarray/base/numel' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var ones = require( '@stdlib/array/ones' );
var flatten = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof flatten, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not an ndarray', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			flatten( value, 1 );
		};
	}
});

tape( 'the function throws an error if provided a first argument with invalid number of dimensions', function test( t ) {
	var values;
	var i;

	values = [
		zeros( [ 2 ] ),
		scalar2ndarray( 1.0 ),
		zeros( [ 5 ] ),
		scalar2ndarray( 10.0 ),
		zeros( [] )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			flatten( value, 1 );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is not a non-negative integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			flatten( zeros( [ 2, 2, 2 ] ), value );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is greater than input ndarray dimensions', function test( t ) {
	var values;
	var i;

	values = [
		4,
		10,
		20,
		15,
		40
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			flatten( zeros( [ 2, 2, 2 ] ), value );
		};
	}
});

tape( 'the function returns a flattened copy of the provided input ndarray (row-major, contiguous)', function test( t ) {
	var expected;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;
	var y;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 3, 1, 2 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	x = ndarray( dt, ones( numel( sh ), dt ), sh, st, o, ord );
	y = flatten( x, 1 );

	expected = [ 3, 2 ];

	t.strictEqual( isSameFloat64Array( x.data, y.data ), true, 'returns expected value' );
	t.deepEqual( getShape( y ), expected, 'returns expected value' );
	t.strictEqual( getDtype( x ), getDtype( y ), 'returns expected value' );
	t.strictEqual( getOrder( x ), getOrder( y ), 'returns expected value' );

	y = flatten( x, 2 );

	expected = [ 6 ];

	t.strictEqual( isSameFloat64Array( x.data, y.data ), true, 'returns expected value' );
	t.deepEqual( getShape( y ), expected, 'returns expected value' );
	t.strictEqual( getDtype( x ), getDtype( y ), 'returns expected value' );
	t.strictEqual( getOrder( x ), getOrder( y ), 'returns expected value' );

	t.end();
});

tape( 'the function returns a flattened copy of the provided input ndarray (row-major, contiguous, accessors)', function test( t ) {
	var expected;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;
	var y;

	dt = 'complex128';
	ord = 'row-major';
	sh = [ 3, 1, 2 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	x = ndarray( dt, ones( numel( sh ), dt ), sh, st, o, ord );

	y = flatten( x, 1 );

	expected = [ 3, 2 ];

	t.strictEqual( isSameComplex128Array( x.data, y.data ), true, 'returns expected value' );
	t.deepEqual( getShape( y ), expected, 'returns expected value' );
	t.strictEqual( getDtype( x ), getDtype( y ), 'returns expected value' );
	t.strictEqual( getOrder( x ), getOrder( y ), 'returns expected value' );

	y = flatten( x, 2 );

	expected = [ 6 ];

	t.strictEqual( isSameComplex128Array( x.data, y.data ), true, 'returns expected value' );
	t.deepEqual( getShape( y ), expected, 'returns expected value' );
	t.strictEqual( getDtype( x ), getDtype( y ), 'returns expected value' );
	t.strictEqual( getOrder( x ), getOrder( y ), 'returns expected value' );

	t.end();
});
